var t=`0891-dhal-curry`;var n=`world-0891`;var s=`LK`;var r=`south-asia`;var a=4;var l=46;var o={en:`Dhal Curry`,ua:`Сочевичне карі`};var u={en:`Dhal Curry is a Sri Lanka dish made with red lentils, yellow onion, fresh curry leaves, coconut milk. This home-scale recipe assigns measured ingredients to the steps where they are used.`,ua:`Сочевичне карі, страва кухні країни Шрі-Ланка. Основні складники: червона сочевиця, жовта цибуля, свіже листя карі, кокосове молоко. Кількості у цьому домашньому рецепті прив’язані до відповідних етапів.`};var d=[{en:`Cook the listed ingredients in simmering water for about 22 minutes until tender; drain well if necessary.`,ua:`Варіть зазначені складники у воді приблизно 22 хвилин до м’якості; за потреби добре злийте воду.`,t:[`boiling`],m:22,i:[[`red-lentils`,330,`g`],[`water`,950,`ml`],[`ground-turmeric`,4,`g`]]},{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 7 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 7 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:7,i:[[`yellow-onion`,165,`g`],[`coconut-oil`,37,`ml`],[`mustard-seeds`,5,`g`],[`fresh-curry-leaves`,12,`leaf`]]},{en:`Combine the remaining ingredients, cover partly and stew gently for about 14 minutes until the flavors meld and everything is tender.`,ua:`З’єднайте решту складників, частково накрийте й тушкуйте приблизно 14 хвилин до поєднання смаків і м’якості продуктів.`,t:[`stewing`],m:14,i:[[`coconut-milk`,310,`ml`],[`serrano-pepper`,2,`pcs`],[`table-salt`,null,`to_taste`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`lime`,1,`pcs`]]}];var m={slug:t,id:n,country:`LK`,region:r,servings:4,minutes:46,title:o,text:u,steps:d};export{s as country,m as default,n as id,l as minutes,r as region,a as servings,t as slug,d as steps,u as text,o as title};